POLICIES = {
    "org": {"allowedRegions": "us,eu", "disableSAKeys": "true"},
    "folder:prod": {"allowedRegions": "eu"},
    "project:api-prod": {},
}
CHAIN = ["org", "folder:prod", "project:api-prod"]

def effective_policy(chain, policies):
    result = {}
    for level in chain:
        for constraint, value in policies.get(level, {}).items():
            result[constraint] = (value, level)
    return result

eff = effective_policy(CHAIN, POLICIES)
print("project:api-prod effective policy:")
for constraint in sorted(eff):
    value, source = eff[constraint]
    print(f"{constraint} = {value} (set at {source})")
